    const TT = {key:Y.key, name:Y.name, closed:false, q:0, ti, bb:[1e9, 1e9, -1e9, -1e9], cranes:[], work:[], trucks:[], rtgs:[], picks:[], scs:[], tugs:[], ships:[], zones:[], rail:true};
    PORT.T.push(TT);
    for (const p of Y.zone){ TT.bb[0] = Math.min(TT.bb[0], p[0]); TT.bb[1] = Math.min(TT.bb[1], p[1]); TT.bb[2] = Math.max(TT.bb[2], p[0]); TT.bb[3] = Math.max(TT.bb[3], p[1]); }
